//! Structural Schema V3 attestations generated by the Truth owner itself.
//!
//! These are derived from the strict, owner-native Rust DTOs, not a caller's
//! hand-authored parameter JSON. Install them only through the trusted catalog;
//! they grant no Temporal/SQL authority by their mere presence.

use std::collections::BTreeMap;
use std::convert::Infallible;

use operation_protocol::{
    ArtifactSchema, ArtifactTypeId, Operation, OperationRef, OwnerDtoDescriptorFormatV3,
    OwnerDtoDescriptorV3, OwnerOperationSchemaV3, OwnerSchemaErrorV3, PinnedOwnerOperationSchemaV3,
    PlanError, PortId, OWNER_SCHEMA_ATTESTATION_REVISION_V3,
};
use schemars::{generate::SchemaSettings, JsonSchema};

use crate::operations::{DetectContradictionsV1, JudgeCompletenessV1, PureTruthOperation};

fn descriptor<T: JsonSchema>(
    artifact: &ArtifactSchema,
    serializing: bool,
) -> Result<OwnerDtoDescriptorV3, OwnerSchemaErrorV3> {
    let generator = SchemaSettings::draft2020_12();
    let generator = if serializing {
        generator.for_serialize()
    } else {
        generator.for_deserialize()
    };
    let root = generator.into_generator().into_root_schema_for::<T>();
    let descriptor_bytes = serde_json::to_vec(&root).map_err(|error| {
        OwnerSchemaErrorV3::InvalidV2Contract(PlanError::Serialization(error.to_string()))
    })?;
    Ok(OwnerDtoDescriptorV3 {
        schema_id: artifact.id.clone(),
        revision: artifact.revision,
        format: OwnerDtoDescriptorFormatV3::JsonSchema2020_12,
        descriptor_bytes,
    })
}

fn pinned<O>() -> Result<PinnedOwnerOperationSchemaV3, OwnerSchemaErrorV3>
where
    O: PureTruthOperation<Failure = Infallible>,
    O::Input: JsonSchema,
    O::Output: JsonSchema,
{
    let contract = O::contract();
    if contract.inputs.len() != 1 || contract.outputs.len() != 1 {
        return Err(OwnerSchemaErrorV3::PortDescriptorMismatch);
    }
    let (input_port, input_schema) = contract
        .inputs
        .iter()
        .next()
        .ok_or(OwnerSchemaErrorV3::PortDescriptorMismatch)?;
    let (output_port, output_schema) = contract
        .outputs
        .iter()
        .next()
        .ok_or(OwnerSchemaErrorV3::PortDescriptorMismatch)?;
    OwnerOperationSchemaV3 {
        schema_revision: OWNER_SCHEMA_ATTESTATION_REVISION_V3,
        operation: contract.reference.clone(),
        owner: contract.owner.clone(),
        v2_contract_fingerprint: contract.fingerprint()?,
        inputs: BTreeMap::<PortId, OwnerDtoDescriptorV3>::from([(
            input_port.clone(),
            descriptor::<O::Input>(input_schema, false)?,
        )]),
        outputs: BTreeMap::<PortId, OwnerDtoDescriptorV3>::from([(
            output_port.clone(),
            descriptor::<O::Output>(output_schema, true)?,
        )]),
        failure: OwnerDtoDescriptorV3 {
            schema_id: ArtifactTypeId::from("truth.infallible_failure"),
            revision: 1,
            format: OwnerDtoDescriptorFormatV3::JsonSchema2020_12,
            descriptor_bytes: b"false".to_vec(),
        },
    }
    .seal(&contract)
}

/// Exact source-of-truth descriptors for TR-02 and TR-03 pure DTOs.
/// No effect owner route is created, and no future Truth write is admitted.
pub fn truth_pure_operation_owner_schemas(
) -> Result<BTreeMap<OperationRef, PinnedOwnerOperationSchemaV3>, OwnerSchemaErrorV3> {
    let schemas = [pinned::<JudgeCompletenessV1>()?, pinned::<DetectContradictionsV1>()?];
    Ok(schemas
        .into_iter()
        .map(|schema| (schema.schema.operation.clone(), schema))
        .collect())
}
